import math

def check_solution(m, n, p):
    """Checks if (m, n, p) satisfies the conditions."""
    try:
        # Check m^2 + n = p^a
        val1 = m**2 + n
        if val1 <= 0 or p <= 1:
            return False
        a = round(math.log(val1, p))
        if abs(val1 - p**a) > 1e-9 or a <= 1:
            return False

        # Check m + n^2 = p^b
        val2 = m + n**2
        if val2 <= 0 or p <= 1:
            return False
        b = round(math.log(val2, p))
        if abs(val2 - p**b) > 1e-9 or b <= 1:
            return False

        return (True, a, b)
    except ValueError:
        return (False, None, None)

# 1. Verification of known solutions
solutions_to_verify = [(2, 5, 3), (5, 2, 3)]
print("--- Verification of Known Solutions ---")
for m, n, p in solutions_to_verify:
    is_valid, a, b = check_solution(m, n, p)
    if is_valid:
        print(f"Verified ({m}, {n}, {p}): m^2+n = {p}^{a} ({m**2+n}), m+n^2 = {p}^{b} ({m+n**2}). Valid.")
    else:
        print(f"Verification failed for ({m}, {n}, {p}).")

# 2. Limited Search for p=7 up to 7^4
p = 7
powers_of_p = [7**a for a in range(2, 5)] # 7^2, 7^3, 7^4
print("\n--- Limited Search for p=7 (Powers up to 7^4) ---")
found_p7_solutions = []

# Iterate over possible powers for the first equation: m^2 + n = 7^a
for target_p_a in powers_of_p:
    # m^2 < target_p_a, so m < sqrt(target_p_a)
    m_max = int(math.sqrt(target_p_a - 1))
    for m in range(1, m_max + 1):
        n = target_p_a - m**2
        if n < 1:
            continue # Should not happen if m_max is calculated correctly

        # Check the second equation: m + n^2 = 7^b
        target_m_plus_n2 = m + n**2

        # Check if target_m_plus_n2 is a power of 7 greater than 1
        if target_m_plus_n2 > 1:
            try:
                b_float = math.log(target_m_plus_n2, p)
                b = round(b_float)

                # Check if b is an integer and b >= 2
                if abs(b_float - b) < 1e-9 and b >= 2:
                    # Found a solution candidate
                    # Double check the original constraints just in case floating point issues caused confusion
                    is_valid, a_check, b_check = check_solution(m, n, p)
                    if is_valid:
                        solution = (m, n, p)
                        if solution not in found_p7_solutions:
                            found_p7_solutions.append(solution)
                            print(f"Solution found: {solution}. Exponents (a, b) = ({a if abs(math.log(target_p_a, p)) - a < 1e-9 else 'N/A'}, {b}).")

            except ValueError:
                # target_m_plus_n2 is not a positive number, or p=1
                pass

print("\nSearch complete.")
